import { MakeLogicType, afterMount, connect, kea, path } from 'kea'

import { liveTicketsLogic, sidepanelTicketsLogic } from '../../components/SidePanel/sidepanelTicketsLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface myTicketsSceneLogicValues {
    ticketsRequestsInFlight: number // sidepanelTicketsLogic
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface myTicketsSceneLogicActions {
    loadTickets: (force?: boolean | undefined) => {
        force: boolean
    } // liveTicketsLogic
}

export type myTicketsSceneLogicType = MakeLogicType<myTicketsSceneLogicValues, myTicketsSceneLogicActions>

export const myTicketsSceneLogic = kea<myTicketsSceneLogicType>([
    path(['products', 'conversations', 'frontend', 'scenes', 'myTickets', 'myTicketsSceneLogic']),
    connect(() => ({
        values: [sidepanelTicketsLogic, ['ticketsRequestsInFlight']],
        actions: [liveTicketsLogic, ['loadTickets']],
    })),
    afterMount(({ actions, values }) => {
        if (values.ticketsRequestsInFlight === 0) {
            actions.loadTickets()
        }
    }),
])
